catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    var isAllChecked = (newValue == 'true'); // 전체가 체크되면 true

    // 나머지 모든 변수들을 전체 체크 상태와 동일하게 맞춤
    var fields = ['u_internal', 'u_employee', 'u_consultant', 'u_partner', 'u_external', 'u_vendor', 'u_agency'];

    for (var i = 0; i < fields.length; i++) {
        g_form.setValue(fields[i], isAllChecked);
    }
}
